import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.CWpttWmj.js";const k=JSON.parse('{"title":"Your primary name","description":"","frontmatter":{},"headers":[],"relativePath":"guide/primary-name.md","filePath":"guide/primary-name.md","lastUpdated":1785888355000}'),r={name:"guide/primary-name.md"};function n(o,e,l,h,d,p){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="your-primary-name" tabindex="-1">Your primary name <a class="header-anchor" href="#your-primary-name" aria-label="Permalink to &quot;Your primary name&quot;">​</a></h1><p>A primary name is what apps display <strong>instead of your address</strong>. Setting it turns <code>0x3dC38247c4f9672B2C98aCfdc5C1302f8d897E9C</code> into <code>alice.arc</code> everywhere your wallet appears.</p><h2 id="forward-and-reverse-are-separate" tabindex="-1">Forward and reverse are separate <a class="header-anchor" href="#forward-and-reverse-are-separate" aria-label="Permalink to &quot;Forward and reverse are separate&quot;">​</a></h2><p>Registering <code>alice.arc</code> makes the name point at your address. It does <strong>not</strong> make your address point back at the name. Those are two different records in two different places:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  forward:  alice.arc  ──►  0x3dC3…7E9C     set at registration</span></span>
<span class="line"><span>  reverse:  0x3dC3…7E9C ──►  alice.arc      you must set this</span></span></code></pre></div><p>The forward record is the one that matters for receiving funds. The reverse record is purely cosmetic — it controls how you are <em>displayed</em>. Everything keeps working without it.</p><p>This separation is deliberate. One address may be the target of many names, but it can only have one display name, and only the address&#39;s owner should get to choose which.</p><h2 id="setting-it" tabindex="-1">Setting it <a class="header-anchor" href="#setting-it" aria-label="Permalink to &quot;Setting it&quot;">​</a></h2><p><strong>My names → the name → Records → Use as primary name.</strong> One transaction.</p><p>Under the hood this writes a <code>name</code> text record on your address&#39;s reverse node, via the reverse registrar. The button is disabled once the name is already your primary.</p><p>You can only set a primary name to a name that resolves to you — otherwise the verification below fails and apps will ignore it.</p><h2 id="verification-and-why-it-matters" tabindex="-1">Verification, and why it matters <a class="header-anchor" href="#verification-and-why-it-matters" aria-label="Permalink to &quot;Verification, and why it matters&quot;">​</a></h2><p>Anyone can write anything into their own reverse record. Nothing stops an attacker from setting theirs to <code>vitalik.arc</code>. A reverse record on its own is a <strong>claim</strong>, not proof.</p><p>Proof is the round-trip:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  0xATTACKER ──reverse──► &quot;vitalik.arc&quot; ──forward──► 0xVITALIK</span></span>
<span class="line"><span>                                                         │</span></span>
<span class="line"><span>                                        0xVITALIK ≠ 0xATTACKER  →  unverified</span></span></code></pre></div><p>The UniversalResolver does this check for you and returns the result alongside the name:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">string</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> memory</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">bool</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> verified) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> universalResolver.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reverse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(addr);</span></span></code></pre></div><div class="danger custom-block"><p class="custom-block-title">Integrators: never display an unverified name</p><p>If <code>verified</code> is false, show the raw address. A reverse name that doesn&#39;t round-trip is an impersonation vector, and displaying it is how users get phished.</p><p>The Arc Names app only renders a primary name when <code>verified</code> is true.</p></div><h2 id="when-your-primary-name-stops-verifying" tabindex="-1">When your primary name stops verifying <a class="header-anchor" href="#when-your-primary-name-stops-verifying" aria-label="Permalink to &quot;When your primary name stops verifying&quot;">​</a></h2><p>The round-trip breaks if the forward record changes. Common causes:</p><table tabindex="0"><thead><tr><th>What happened</th><th>Fix</th></tr></thead><tbody><tr><td>You changed the name&#39;s <code>addr</code> record to a different wallet</td><td>Point it back, or set a different primary name.</td></tr><tr><td>You transferred the name away</td><td>Set a primary name you still own.</td></tr><tr><td>The name expired</td><td><a href="/docs/guide/renewals.html">Renew it</a>. Expired names don&#39;t resolve.</td></tr><tr><td>You moved wallets</td><td>Set the reverse record from the new wallet, and point the name at it.</td></tr></tbody></table><p>When this happens apps fall back to showing your address. Nothing is lost, and nothing is at risk — the display just reverts.</p><h2 id="changing-or-clearing-it" tabindex="-1">Changing or clearing it <a class="header-anchor" href="#changing-or-clearing-it" aria-label="Permalink to &quot;Changing or clearing it&quot;">​</a></h2><p>Setting a different name overwrites the record — there&#39;s no need to clear the old one first. To remove the primary name entirely, set the reverse record to an empty string.</p><h2 id="one-name-many-wallets" tabindex="-1">One name, many wallets <a class="header-anchor" href="#one-name-many-wallets" aria-label="Permalink to &quot;One name, many wallets&quot;">​</a></h2><p>A single name can be the primary name of only one address at a time, because the record lives on the address, not the name. If you want <code>alice.arc</code> to display for two wallets, only one of them can round-trip successfully, since <code>addr</code> holds a single address.</p><p>For multiple wallets, register a name each — or point subdomain-style names at each wallet.</p><h2 id="reading-it-programmatically" tabindex="-1">Reading it programmatically <a class="header-anchor" href="#reading-it-programmatically" aria-label="Permalink to &quot;Reading it programmatically&quot;">​</a></h2><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">verified</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">readContract</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  address: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UNIVERSAL_RESOLVER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  abi: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">UNIVERSAL_RESOLVER_ABI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  functionName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;reverse&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  args: [userAddress],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> display</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> verified </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> name </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> shortenAddress</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(userAddress);</span></span></code></pre></div><p>The manual path — deriving the reverse node yourself and verifying by hand — is documented in <a href="/docs/protocol/resolving.html#reverse-resolution">Resolving .arc</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/docs/guide/records.html">Records &amp; profile</a> — the rest of your profile.</li><li><a href="/docs/protocol/resolving.html">Resolving .arc</a> — the resolution algorithm in full.</li><li><a href="/docs/safety.html#look-alike-names">Safety</a> — impersonation and how to spot it.</li></ul>`,32)])])}const m=a(r,[["render",n]]);export{k as __pageData,m as default};
